  "std-tabs": {
    "name": "std-tabs",
    "version": "1.0.0",
    "description": "Tabbed navigation within a page",
    "theme": {
      "name": "ui-slate",
      "tokens": {
        "colors": {
          "primary": "#475569",
          "primary-hover": "#334155",
          "primary-foreground": "#ffffff",
          "accent": "#64748b",
          "accent-foreground": "#ffffff",
          "success": "#22c55e",
          "warning": "#f59e0b",
          "error": "#ef4444"
        }
      }
    },
    "orbitals": [
      {
        "name": "TabsOrbital",
        "entity": {
          "name": "TabContent",
          "persistence": "runtime",
          "collection": "tabcontents",
          "fields": [
            {
              "name": "id",
              "type": "string",
              "required": true
            },
            {
              "name": "activeTab",
              "type": "string",
              "default": "overview"
            }
          ]
        },
        "traits": [
          {
            "name": "TabNavigation",
            "linkedEntity": "TabContent",
            "category": "interaction",
            "stateMachine": {
              "states": [
                {
                  "name": "active",
                  "isInitial": true
                }
              ],
              "events": [
                {
                  "key": "INIT",
                  "name": "Initialize"
                },
                {
                  "key": "SELECT_TAB",
                  "name": "Select Tab",
                  "payload": [
                    {
                      "name": "tabId",
                      "type": "string",
                      "required": true
                    }
                  ]
                }
              ],
              "transitions": [
                {
                  "from": "active",
                  "to": "active",
                  "event": "INIT",
                  "effects": [
                    [
                      "fetch",
                      "TabContent"
                    ],
                    [
                      "render-ui",
                      "main",
                      {
                        "type": "stack",
                        "direction": "vertical",
                        "gap": "lg",
                        "children": [
                          {
                            "type": "stack",
                            "direction": "horizontal",
                            "gap": "md",
                            "justify": "space-between",
                            "children": [
                              {
                                "type": "stack",
                                "direction": "horizontal",
                                "gap": "md",
                                "children": [
                                  {
                                    "type": "icon",
                                    "name": "layers",
                                    "size": "lg"
                                  },
                                  {
                                    "type": "typography",
                                    "content": "Tabs",
                                    "variant": "h2"
                                  }
                                ]
                              },
                              {
                                "type": "button",
                                "label": "Add Tab",
                                "event": "SELECT_TAB",
                                "icon": "plus",
                                "variant": "primary"
                              }
                            ]
                          },
                          {
                            "type": "divider"
                          },
                          {
                            "type": "tabs",
                            "entity": "TabContent",
                            "onTabChange": "SELECT_TAB",
                            "tabs": [
                              {
                                "id": "overview",
                                "label": "Overview"
                              },
                              {
                                "id": "details",
                                "label": "Details"
                              },
                              {
                                "id": "settings",
                                "label": "Settings"
                              }
                            ]
                          }
                        ]
                      }
                    ]
                  ]
                },
                {
                  "from": "active",
                  "to": "active",
                  "event": "SELECT_TAB",
                  "effects": [
                    [
                      "set",
                      "@entity.activeTab",
                      "@payload.tabId"
                    ]
                  ]
                }
              ]
            }
          }
        ],
        "pages": [
          {
            "name": "TabsPage",
            "path": "/tabs",
            "isInitial": true,
            "traits": [
              {
                "ref": "TabNavigation"
              }
            ]
          }
        ]
      }
    ]
  },
